# Change `tls-defaults-hardening` (fixture): environments get an explicit TLS mode and
# the DSN builders enforce it. Production moves to verify-full; staging keeps require.
ENVIRONMENT_SSLMODES = {"production": "verify-full", "staging": "require"}


def build_dsn_for_environment(environment: str, *, host: str, database: str, user: str) -> str:
    """Build a DSN whose sslmode is the one the environment declares."""
    try:
        mode = ENVIRONMENT_SSLMODES[environment]
    except KeyError as exc:
        raise ValueError(f"unknown environment: {environment}") from exc
    return build_dsn(host=host, database=database, user=user, sslmode=mode)


def assert_environment_tls(environment: str, dsn: str) -> str:
    """Verify a DSN is at least as strict as the environment requires."""
    mode = assert_tls(dsn)
    required = ENVIRONMENT_SSLMODES.get(environment)
    if required is None:
        raise ValueError(f"unknown environment: {environment}")
    if required == "verify-full" and mode != "verify-full":
        raise InsecureConfiguration(f"{environment} requires verify-full, DSN uses {mode}")
    return mode
